-- fdh-c-check: op row count of AER
-- GENERATED by scripts/export_rules.mjs from BKH Insight src/app/api/fdh/c-check/checks.ts - do not edit by hand
-- params (2, in order of the placeholders): start, end
-- returns n
WITH p AS (SELECT CAST(? AS DATE) AS s, CAST(? AS DATE) AS e) SELECT COUNT(*) AS n FROM p JOIN ovst v ON v.vstdate BETWEEN p.s AND p.e LEFT JOIN er_regist er ON er.vn = v.vn LEFT JOIN referin rin ON rin.vn = v.vn AND TRIM(COALESCE(rin.refer_hospcode, rin.hospcode, '')) NOT IN ('', (SELECT hospitalcode FROM opdconfig LIMIT 1)) WHERE (v.an IS NULL OR v.an = '') AND (er.vn IS NOT NULL OR rin.vn IS NOT NULL OR EXISTS (SELECT 1 FROM referout r WHERE r.vn = v.vn AND TRIM(COALESCE(r.refer_hospcode, r.hospcode, '')) NOT IN ('', (SELECT hospitalcode FROM opdconfig LIMIT 1))));
